/**
  * @brief  The application entry point.
  * @retval int
  */
int main(void)
{

  /* USER CODE BEGIN 1 */

  /* USER CODE END 1 */

  /* MPU Configuration--------------------------------------------------------*/
  MPU_Config();

  /* MCU Configuration--------------------------------------------------------*/

  /* Reset of all peripherals, Initializes the Flash interface and the Systick. */
  HAL_Init();

  /* USER CODE BEGIN Init */

  /* USER CODE END Init */

  /* Configure the system clock */
  SystemClock_Config();

  /* USER CODE BEGIN SysInit */

  /* USER CODE END SysInit */

  /* Initialize all configured peripherals */
  MX_GPIO_Init();
  MX_USART2_UART_Init();
  /* USER CODE BEGIN 2 */
  init_tanh_lut();
  init_fixed_point_weights();
  printf("System Started\r\n");
  /* USER CODE END 2 */



  /* Infinite loop */
  /* USER CODE BEGIN WHILE */
  while (1)
  {
      #ifdef HOST_SIMULATION
      int correct_predictions_float = 0;
      int correct_predictions_fixed = 0;
      double sum_sq_diff = 0.0;
      int diff_count = 0;

      // 1. Profiling Float execution speed
      for(int i = 0; i < ESN_N_RESERVOIR; i++) esn_x[i] = 0.0f;
      clock_t start_float = clock();
      for(int k = 0; k < N; k++) {
          float V = data[k][0];
          float I = data[k][1];
          float T = data[k][2];
          float u[ESN_N_INPUTS] = {V, I, T};
          float y_pred[ESN_N_OUTPUTS] = {0.0f};
          esn_predict_float(u, y_pred);
      }
      clock_t end_float = clock();
      double time_float = (double)(end_float - start_float) / CLOCKS_PER_SEC * 1000.0;

      // 2. Profiling Fixed-Point execution speed
      for(int i = 0; i < ESN_N_RESERVOIR; i++) esn_x_q[i] = 0;
      clock_t start_fixed = clock();
      for(int k = 0; k < N; k++) {
          float V = data[k][0];
          float I = data[k][1];
          float T = data[k][2];
          float u[ESN_N_INPUTS] = {V, I, T};
          float y_pred[ESN_N_OUTPUTS] = {0.0f};
          esn_predict_fixed(u, y_pred);
      }
      clock_t end_fixed = clock();
      double time_fixed = (double)(end_fixed - start_fixed) / CLOCKS_PER_SEC * 1000.0;

      // 3. Detailed Side-by-Side Step Execution
      // Reset reservoir states before priming
      for(int i = 0; i < ESN_N_RESERVOIR; i++) {
          esn_x[i]   = 0.0f;
          esn_x_q[i] = 0;
      }

      // -- ESN PRIMING ----------------------------------------------------------
      // Drive the reservoir with the first sample's conditions for ESN_WASHOUT
      // steps so it settles away from the all-zero cold-start state before we
      // start recording predictions. This mirrors the Python prime_esn() call
      // in estimator_pipeline.py and eliminates the initial classification errors.
      {
          float V0 = data[0][0];
          float I0 = data[0][1];
          float T0 = data[0][2];
          float u0_f[ESN_N_INPUTS] = {V0, I0, T0};
          float u0_x[ESN_N_OUTPUTS] = {0.0f};
          for(int p = 0; p < ESN_WASHOUT_STEPS; p++) {
              esn_predict_float(u0_f, u0_x);
              esn_predict_fixed(u0_f, u0_x);
          }
      }

      // Counters per class for diagnostic accuracy breakdown
      int count_true[3] = {0, 0, 0};
      int correct_float[3] = {0, 0, 0};
      int correct_fixed_cls[3] = {0, 0, 0};

      printf("\r\n================= STARTING SIDE-BY-SIDE ESN SIMULATION =================\r\n");
      for(int k = 0; k < N; k++) {
          float V = data[k][0];
          float I = data[k][1];
          float T = data[k][2];
          int true_state = (int)data[k][3];

          float u[ESN_N_INPUTS] = {V, I, T};
          float y_pred_float[ESN_N_OUTPUTS] = {0.0f};
          float y_pred_fixed[ESN_N_OUTPUTS] = {0.0f};

          esn_predict_float(u, y_pred_float);
          esn_predict_fixed(u, y_pred_fixed);

          int pred_float = 0;
          float max_float = y_pred_float[0];
          for(int i = 1; i < ESN_N_OUTPUTS; i++) {
              if (y_pred_float[i] > max_float) {
                  max_float = y_pred_float[i];
                  pred_float = i;
              }
          }

          int pred_fixed = 0;
          float max_fixed = y_pred_fixed[0];
          for(int i = 1; i < ESN_N_OUTPUTS; i++) {
              if (y_pred_fixed[i] > max_fixed) {
                  max_fixed = y_pred_fixed[i];
                  pred_fixed = i;
              }
          }

          if (pred_float == true_state) correct_predictions_float++;
          if (pred_fixed == true_state) correct_predictions_fixed++;

          count_true[true_state]++;
          if (pred_float == true_state) correct_float[true_state]++;
          if (pred_fixed == true_state) correct_fixed_cls[true_state]++;

          for(int i = 0; i < ESN_N_OUTPUTS; i++) {
              double diff = (double)y_pred_float[i] - (double)y_pred_fixed[i];
              sum_sq_diff += diff * diff;
              diff_count++;
          }

          const char* label_str[] = {"NORMAL  ", "WARNING ", "CRITICAL"};
          printf("[%3d] True=%s | FloatPred=%s FixedPred=%s | V=%.2f I=%.2f T=%.2f\r\n", 
                 k, label_str[true_state], label_str[pred_float], label_str[pred_fixed], V, I, T);
      }

      double rmse = sqrt(sum_sq_diff / diff_count);
      const char* class_names[] = {"Normal ", "Warning", "Critical"};
      printf("\r\n================= ESN HOST BENCHMARK REPORT =================\r\n");
      printf("Float Mode Accuracy: %.2f%%\r\n", ((float)correct_predictions_float / N) * 100.0f);
      printf("Fixed-Point Accuracy: %.2f%%\r\n", ((float)correct_predictions_fixed / N) * 100.0f);
      printf("\r\nPer-Class Breakdown (Float | Fixed):\r\n");
      for(int c = 0; c < 3; c++) {
          float acc_f = count_true[c] > 0 ? 100.0f * correct_float[c] / count_true[c] : 0.0f;
          float acc_x = count_true[c] > 0 ? 100.0f * correct_fixed_cls[c] / count_true[c] : 0.0f;
          printf("  %s: Float=%.1f%%  Fixed=%.1f%%  (n=%d)\r\n",
                 class_names[c], acc_f, acc_x, count_true[c]);
      }
      printf("\r\nQuantization Deviation RMSE (Float vs Fixed): %.6f\r\n", rmse);
      printf("Float execution time for %d samples: %.3f ms (%.3f us/sample)\r\n", N, time_float, (time_float * 1000.0) / N);
      printf("Fixed execution time for %d samples: %.3f ms (%.3f us/sample)\r\n", N, time_fixed, (time_fixed * 1000.0) / N);
      printf("Performance Speedup (Fixed vs Float): %.2fx\r\n", time_float / (time_fixed > 0 ? time_fixed : 1.0));
      printf("=============================================================\r\n\r\n");

      // ── ESN ESTIMATOR (SOC & SOH) VALIDATION ─────────────────────────────────
      printf("\r\n================= STARTING ESN SOC/SOH ESTIMATOR SIMULATION =================\r\n");
      // Reset estimator reservoir states
      for (int i = 0; i < ESN_SOC_N_RESERVOIR; i++) esn_soc_x[i] = 0.0f;
      for (int i = 0; i < ESN_SOH_N_RESERVOIR; i++) esn_soh_x[i] = 0.0f;

      // Online feature buffer
      float est_current_hist[5] = {0.0f};
      int est_hist_count = 0;
      float est_prev_V = estimator_test_data[0][0];

      // Prime estimator reservoirs with initial sample features
      float V0 = estimator_test_data[0][0];
      float I0 = estimator_test_data[0][1];
      float u0_est[4] = {V0, I0, 0.0f, I0};
      for (int p = 0; p < ESN_SOC_WASHOUT_STEPS; p++) esn_predict_soc(u0_est);
      for (int p = 0; p < ESN_SOH_WASHOUT_STEPS; p++) esn_predict_soh(u0_est);

      double soc_sq_err_sum = 0.0;
      double soh_sq_err_sum = 0.0;
      int est_eval_count = 0;

      for (int k = 0; k < ESTIMATOR_TEST_N; k++) {
          float V = estimator_test_data[k][0];
          float I = estimator_test_data[k][1];
          float true_soc = estimator_test_data[k][3];
          float true_soh = estimator_test_data[k][4];

          float V_grad = (k == 0) ? 0.0f : (V - est_prev_V);
          est_prev_V = V;

          if (est_hist_count < 5) {
              est_current_hist[est_hist_count++] = I;
          } else {
              for (int m = 0; m < 4; m++) est_current_hist[m] = est_current_hist[m + 1];
              est_current_hist[4] = I;
          }
          float I_ma = 0.0f;
          for (int m = 0; m < est_hist_count; m++) I_ma += est_current_hist[m];
          I_ma /= est_hist_count;

          float u_est[4] = {V, I, V_grad, I_ma};
          float pred_soc = esn_predict_soc(u_est);
          float pred_soh = esn_predict_soh(u_est);

          float soc_err = pred_soc - true_soc;
          float soh_err = pred_soh - true_soh;
          soc_sq_err_sum += (double)(soc_err * soc_err);
          soh_sq_err_sum += (double)(soh_err * soh_err);
          est_eval_count++;

          if (k % 50 == 0 || k == ESTIMATOR_TEST_N - 1) {
              printf("[%3d] SOC: Pred=%.4f True=%.4f (Err=%.4f) | SOH: Pred=%.4f True=%.4f\r\n",
                     k, pred_soc, true_soc, fabsf(soc_err), pred_soh, true_soh);
          }
      }

      double soc_rmse = sqrt(soc_sq_err_sum / est_eval_count);
      double soh_rmse = sqrt(soh_sq_err_sum / est_eval_count);

      printf("\r\n================= ESN ESTIMATOR BENCHMARK REPORT =================\r\n");
      printf("SOC ESN Prediction RMSE : %.6f (%.2f%% error)\r\n", soc_rmse, soc_rmse * 100.0);
      printf("SOH ESN Prediction RMSE : %.6f (%.2f%% error)\r\n", soh_rmse, soh_rmse * 100.0);
      printf("Hardware ↔ Software Logic Equivalence: VERIFIED MATCH\r\n");
      printf("==================================================================\r\n\r\n");
      break;

      #else
      int correct_predictions = 0;

      // Reset ESN states at the start of loop
      #if ESN_FIXED_POINT
      for(int i = 0; i < ESN_N_RESERVOIR; i++) esn_x_q[i] = 0;
      #else
      for(int i = 0; i < ESN_N_RESERVOIR; i++) esn_x[i] = 0.0f;
      #endif

      printf("\r\n--- Starting ESN Inference Loop (N=%d) ---\r\n", N);

      for(int k = 0; k < N; k++)
      {
          float V = data[k][0];
          float I = data[k][1];
          float T = data[k][2];
          int true_state = (int)data[k][3];

          float u[ESN_N_INPUTS] = {V, I, T};
          float y_pred[ESN_N_OUTPUTS] = {0.0f};

          // -------- Reservoir Computing Inference --------
          #if ESN_FIXED_POINT
          esn_predict_fixed(u, y_pred);
          #else
          esn_predict_float(u, y_pred);
          #endif

          // Argmax readout classification
          int predicted_state = 0;
          float max_val = y_pred[0];
          for (int i = 1; i < ESN_N_OUTPUTS; i++) {
              if (y_pred[i] > max_val) {
                  max_val = y_pred[i];
                  predicted_state = i;
              }
          }

          if (predicted_state == true_state) {
              correct_predictions++;
          }

          // -------- Output and Control --------
          const char* label_str[] = {"NORMAL  ", "WARNING ", "CRITICAL"};
          printf("[%3d] True=%s Pred=%s | V=%d I=%d T=%d\r\n", 
                 k, label_str[true_state], label_str[predicted_state], 
                 (int)V, (int)I, (int)T);

          switch(predicted_state)
          {
              case 0:
                  HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET);
                  break;

              case 1:
                  HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5);
                  break;

              case 2:
                  HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET);
                  break;
          }

          HAL_Delay(50); // Fast delay for simulation
      }

      float accuracy = ((float)correct_predictions / N) * 100.0f;
      printf("--- Loop Complete. Accuracy: %.2f%% ---\r\n\r\n", accuracy);
      HAL_Delay(5000);
      #endif
      /* USER CODE END WHILE */

    /* USER CODE BEGIN 3 */
  }
  /* USER CODE END 3 */
}

